-- ================================================================
-- 16_logo_zona_motos_pro.sql — Logo de Zona Motos Pro
-- El sistema guarda el logo como URL en empresas.logo_url; aca va
-- embebido como data URI (PNG 128x128, ~7 KB) para no depender de
-- un bucket de Storage. Se ve en la barra lateral (contenedor 32x32).
-- ================================================================

update empresas
   set logo_url = 'data:image/png;base64,'
 where slug = 'zona-motos-pro';

-- verificacion:
-- select nombre, length(logo_url) from empresas where slug = 'zona-motos-pro';
